sc_cat_item_producer.script:
(function() {


    new x_hccc_hoc_ohs.HoCOHSRecordProducerUtil().createCaseFromProducer(current, producer, cat_item.sys_id);

    if (producer.ohsm_repo_report == '2306fd9c8774ad5050d2eca73cbb3500' || producer.ohsm_repo_report == '55703d708701a99450d2eca73cbb3566') { //LAB1058
        //populate fields for report.
        current.inc_location = producer.ohsm_repo_building;
        current.committee_excemption_pursuant_to_subsection_135_6_a_of_the_act = producer.ohsm_repo_committee_exemption_pursuant_to_subsection_135_6_a_of_the_act;
        current.number_of_employees_represented_by_committee = producer.ohsm_repo_number_of_employees_represented_by_committee;
        current.number_of_trade_union_s_employee_committee_members = producer.ohsm_repo_number_of_trade_union_s_employee_committee_members;
        current.number_of_non_trade_union_employee_committee_members = producer.ohsm_repo_number_of_non_trade_union_employee_comittee_members;
        current.number_of_employer_committee_members = producer.ohsm_repo_number_of_employer_committee_members;
        current.total_committee_membership = producer.ohsm_repo_total_committee_membership;
        current.trade_union_s = producer.ohsm_repo_trade_unions;
        current.subject_person = producer.ohsm_repo_contact_person;
        current.wi_action_taken = producer.ohsm_repo_highlights_programs_inquiries_etc;
        current.employee_chairperson = producer.ohsm_repo_employee_chairperson;
        current.employer_chairperson = producer.ohsm_repo_employer_chairperson;

        //process meetings variable set

        var mtgs = producer.manually_tracked_items;
        var parser = JSON.parse(mtgs);

        var arr = [];

        for (var i = 0; i < parser.length; i++) {
            //create array			
            arr.push(parser[i].ohs_mtgs_january.toString());
            arr.push(parser[i].ohs_mtgs_february.toString());
            arr.push(parser[i].ohs_mtgs_march.toString());
            arr.push(parser[i].ohs_mtgs_april.toString());
            arr.push(parser[i].ohs_mtgs_may.toString());
            arr.push(parser[i].ohs_mtgs_june.toString());
            arr.push(parser[i].ohs_mtgs_july.toString());
            arr.push(parser[i].ohs_mtgs_august.toString());
            arr.push(parser[i].ohs_mtgs_september.toString());
            arr.push(parser[i].ohs_mtgs_october.toString());
            arr.push(parser[i].ohs_mtgs_november.toString());
            arr.push(parser[i].ohs_mtgs_december.toString());
            arr.push(parser[i].ohs_mtg_total.toString());

            if (parser[i].ohs_mtgs_meeting_type == 'regular') {
                //update regular meetings				
                current.meetings_regular = arr.toString();
            } else if (parser[i].ohs_mtgs_meeting_type == 'special') {
                //update special meetings
                current.meeting_special = arr.toString();
            } else {
                current.programs = arr.toString();
            }
            arr.length = 0;
        }

    } 
})();
